import{_ as t,C as s,o as e,c as d,j as i,E as o,a as l,a2 as r}from"./chunks/framework.C21TwvGF.js";const T=JSON.parse(`{"title":"9-dars (Mentor). Ranglar nazariyasi va dizayn asoslari (2-qism): Color Picker, Swatches va Gradient bilan ishlash","description":"","frontmatter":{"title":"9-dars (Mentor). Ranglar nazariyasi va dizayn asoslari (2-qism): Color Picker, Swatches va Gradient bilan ishlash","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"mentor_dars","dars":{"sinf":{"name":"9-sinf (Game)","link":"/mentor/9-sinf-game/"},"week":{"n":3,"link":"/mentor/9-sinf-game/hafta-03/"},"g":9,"title":"Ranglar nazariyasi va dizayn asoslari (2-qism): Color Picker, Swatches va Gradient bilan ishlash","lead":"Ranglar nazariyasi va dizayn asoslari (2-qism): Color Picker, Swatches va Gradient bilan ishlash","slide":"/slaydlar/9-sinf-game/hafta-03/dars-3.html","test":"/slaydlar/9-sinf-game/hafta-03/dars-3-test.html","student_link":"/9-sinf-game/hafta-03/dars-3","tabs":[{"g":7,"link":"/mentor/9-sinf-game/hafta-03/dars-1","current":false},{"g":8,"link":"/mentor/9-sinf-game/hafta-03/dars-2","current":false},{"g":9,"link":"/mentor/9-sinf-game/hafta-03/dars-3","current":true}],"prev":{"g":8,"title":"Ranglar nazariyasi va dizayn asoslari (1-qism): RGB va CMYK, rang g'ildiragi va rang psixologiyasi","link":"/mentor/9-sinf-game/hafta-03/dars-2"},"next":null}},"headers":[],"relativePath":"mentor/9-sinf-game/hafta-03/dars-3.md","filePath":"mentor/9-sinf-game/hafta-03/dars-3.md"}`),h={name:"mentor/9-sinf-game/hafta-03/dars-3.md"},g={class:"blk"},m={id:"dars-rejasi",tabindex:"-1"},u={class:"blk"},c={id:"mentor-konspekti",tabindex:"-1"},k={class:"blk"},y={id:"amaliy-topshiriqlar-va-yechimlar",tabindex:"-1"},q={class:"blk"},b={id:"tezkor-nazorat-savollari",tabindex:"-1"},p={class:"blk"},f={id:"keng-tarqalgan-xatolar-va-ularning-oldini-olish",tabindex:"-1"};function v(z,a,_,S,x,P){const n=s("Icon");return e(),d("div",null,[i("div",g,[i("h2",m,[o(n,{name:"file-text"}),a[0]||(a[0]=l(" Dars rejasi ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#dars-rejasi","aria-label":'Permalink to "<Icon name="file-text" /> Dars rejasi"'},"​",-1))]),a[2]||(a[2]=r("<ul><li><strong>Darsning maqsadi:</strong> O&#39;quvchilarga dizaynning oltin tamoyillarini (kompozitsiya, vizual ierarxiya, kontrast, muvozanat) o&#39;rgatish hamda Adobe Photoshop dasturida ranglar bilan professional ishlash vositalarini — Color Picker (RGB, HEX, HSB), Eyedropper (I), Swatches paneli orqali maxsus o&#39;yin palitralari yaratish va Gradient Tool (G) yordamida dinamik o&#39;yin elementlarini (UI panellari, osmon manzarasi, nurlar) bo&#39;yashni amalda qo&#39;llash ko&#39;nikmasini rivojlantirish.</li><li><strong>Kutiladigan natija:</strong> O&#39;quvchilar Color Picker tizimida HEX va HSB parametrlarini erkin boshqara oladi; o&#39;yin uslubiga mos Swatches palitrasini yig&#39;ib saqlay oladi; 5 xil gradiyent turidan (Linear, Radial, Angle, Reflected, Diamond) o&#39;rinli foydalanib, o&#39;yin UI panellari va atmosferasini chiza oladi.</li><li><strong>Vaqt taqsimoti:</strong><ul><li>O&#39;tgan mavzuni takrorlash (RGB vs CMYK, Itten g&#39;ildiragi va rang psixologiyasi): 10 daqiqa</li><li>Yangi mavzu: Dizayn tamoyillari, Color Picker va Eyedropper vositasi: 20 daqiqa</li><li>Swatches paneli va palitralar arxitekturasi: 15 daqiqa</li><li>Gradient Tool (G) turlari va Gradient Editor amaliyoti: 20 daqiqa</li><li>Amaliy topshiriqlar va dars yakuni: 15 daqiqa</li></ul></li></ul><hr>",2))]),i("div",u,[i("h2",c,[o(n,{name:"file-text"}),a[3]||(a[3]=l(" Mentor konspekti ",-1)),a[4]||(a[4]=i("a",{class:"header-anchor",href:"#mentor-konspekti","aria-label":'Permalink to "<Icon name="file-text" /> Mentor konspekti"'},"​",-1))]),a[5]||(a[5]=r('<h3 id="_1-o-yin-dizaynining-6-ta-asosiy-tamoyili" tabindex="-1">1. O&#39;yin dizaynining 6 ta asosiy tamoyili <a class="header-anchor" href="#_1-o-yin-dizaynining-6-ta-asosiy-tamoyili" aria-label="Permalink to &quot;1. O&#39;yin dizaynining 6 ta asosiy tamoyili&quot;">​</a></h3><ol><li><strong>Kompozitsiya va Balans:</strong> Sahnadagi elementlarning vizual og&#39;irligi bir tomonga og&#39;ib ketmasligi kerak. Simmetrik va asimmetrik muvozanat.</li><li><strong>Vizual Ierarxiya:</strong> O&#39;yinchi ko&#39;zi birinchi navbatda nimani ko&#39;rishi kerak? (1 — Qahramon, 2 — Dushman yoki Maqsad, 3 — HUD, 4 — Fon).</li><li><strong>Kontrast:</strong> O&#39;lcham, shakl yoki rang farqi orqali muhim detalni darhol ajratib ko&#39;rsatish.</li><li><strong>Proportsiya va Ritm:</strong> Elementlar o&#39;lchamlarining mutanosibligi va takrorlanish tartibi (masalan, platformalar orasidagi masofa).</li><li><strong>Tipografiya:</strong> Interfeysdagi matnlar o&#39;yin janriga mos va har qanday sharoitda o&#39;ta o&#39;qishli (readable) bo&#39;lishi lozim.</li><li><strong>Soddalik va Minimalizm:</strong> Keraksiz vizual shovqindan qochish — foydalanuvchi ekranga qaraganda chalg&#39;imasligi shart.</li></ol><h3 id="_2-photoshop-color-picker-va-rang-formatlari" tabindex="-1">2. Photoshop Color Picker va Rang Formatlari <a class="header-anchor" href="#_2-photoshop-color-picker-va-rang-formatlari" aria-label="Permalink to &quot;2. Photoshop Color Picker va Rang Formatlari&quot;">​</a></h3><p>Color Picker oynasi rangni 4 xil matematik tizimda belgilash imkonini beradi:</p><ul><li><strong>HSB (Hue, Saturation, Brightness):</strong> Dizaynerlar uchun eng qulay model: <ul><li><em>Hue (Tus):</em> 0° dan 360° gacha bo&#39;lgan rang burchagi.</li><li><em>Saturation (To&#39;yinganlik):</em> 0% (kulrang) dan 100% gacha (sof yorqin rang).</li><li><em>Brightness (Yorqinlik):</em> 0% (qora) dan 100% gacha (yorug&#39;).</li></ul></li><li><strong>RGB:</strong> Qizil, Yashil, Ko&#39;k kanallari (har biri 0 dan 255 gacha).</li><li><strong>HEX (#RRGGBB):</strong> O&#39;yin dasturlashda va vebda keng ishlatiladigan 16-lik tizimdagi kod (masalan, <code>#FF0000</code> — sof qizil, <code>#00FF00</code> — sof yashil, <code>#FFFFFF</code> — oq).</li><li><strong>Eyedropper Tool (I):</strong> Xolstdagi yoki internetdan olingan namunadagi ixtiyoriy nuqtaga bosib, uning aniq rangini bir zumda tanlab oluvchi pipetka.</li></ul><h3 id="_3-swatches-namunalar-paneli" tabindex="-1">3. Swatches (Namunalar) Paneli <a class="header-anchor" href="#_3-swatches-namunalar-paneli" aria-label="Permalink to &quot;3. Swatches (Namunalar) Paneli&quot;">​</a></h3><ul><li>O&#39;yin dizaynida rang tasodifiy tanlanmaydi — butun o&#39;yin uchun 4-6 ta asosiy rangdan iborat palitra oldindan tasdiqlanadi.</li><li><strong>Palitra yaratish:</strong><ol><li><code>Window -&gt; Swatches</code> paneli ochiladi;</li><li>Tanlangan rangni panelga qo&#39;shish uchun <code>+</code> (Create new swatch) tugmasi bosiladi;</li><li>Yangi guruh papkasi ochilib (<code>Cyberpunk_Palette</code>, <code>Forest_Level</code>), barcha ranglar bitta joyga tiziladi;</li><li>Loyihani boshqa kompyuterga yoki jamoa a&#39;zolariga o&#39;tkazish uchun <code>Export Swatches (.aco)</code> qilinadi.</li></ol></li></ul><h3 id="_4-gradient-tool-g-—-rang-o-tishlari" tabindex="-1">4. Gradient Tool (G) — Rang O&#39;tishlari <a class="header-anchor" href="#_4-gradient-tool-g-—-rang-o-tishlari" aria-label="Permalink to &quot;4. Gradient Tool (G) — Rang O&#39;tishlari&quot;">​</a></h3><p>Ranglarning biridan ikkinchisiga mayin oqib o&#39;tish vositasi:</p><ol><li><strong>Linear Gradient (Chiziqli):</strong> To&#39;g&#39;ri chiziq bo&#39;ylab rang o&#39;tishi. Quyosh chiqishi/botishi osmoni, HP bar paneli uchun.</li><li><strong>Radial Gradient (Aylanma):</strong> Markazdan tashqariga doira shaklida tarqaluvchi nur. Mash&#39;ala nuri, sehrli qalqon, o&#39;yin menyusidagi yorug&#39;lik nuqtasi.</li><li><strong>Angle Gradient (Burchakli):</strong> Markaz atrofida 360 daraja soat strelkasi bo&#39;ylab aylanuvchi konus. Radar skaneri yoki metall disk yaltirashi uchun.</li><li><strong>Reflected Gradient (Akslantirilgan):</strong> Markaziy chiziqning ikki tomoniga ko&#39;zgu kabi simmetrik o&#39;tuvchi nur. Qilich tig&#39;ining yaltirashi yoki metall naychalar.</li><li><strong>Diamond Gradient (Olmos shaklli):</strong> Romb/olmos shaklidagi yorug&#39;lik aksi. Qimmatbaho javohirlar va yulduzlar yaraqlashi uchun.</li></ol><h3 id="_5-gradient-editor-gradiyent-muharriri" tabindex="-1">5. Gradient Editor (Gradiyent Muharriri) <a class="header-anchor" href="#_5-gradient-editor-gradiyent-muharriri" aria-label="Permalink to &quot;5. Gradient Editor (Gradiyent Muharriri)&quot;">​</a></h3><ul><li>Yuqori paneldagi gradiyent chizig&#39;iga bosilganda ochiladi.</li><li><strong>Pastki slayderlar (Color Stops):</strong> Ranglarni belgilaydi. Sichqoncha bilan yangi nuqta qo&#39;shish yoki o&#39;chirish mumkin.</li><li><strong>Yuqori slayderlar (Opacity Stops):</strong> Gradiyentning turli nuqtalaridagi shaffoflikni (0% dan 100% gacha) boshqaradi.</li><li><strong>Smoothness (Mayinlik):</strong> Ranglar bir-biriga qanchalik silliq o&#39;tishini foizda sozlaydi.</li></ul><hr>',13))]),i("div",k,[i("h2",y,[o(n,{name:"file-text"}),a[6]||(a[6]=l(" Amaliy topshiriqlar va yechimlar ",-1)),a[7]||(a[7]=i("a",{class:"header-anchor",href:"#amaliy-topshiriqlar-va-yechimlar","aria-label":'Permalink to "<Icon name="file-text" /> Amaliy topshiriqlar va yechimlar"'},"​",-1))]),a[8]||(a[8]=r('<h3 id="_1-topshiriq-color-picker-da-hsb-va-hex-kodi-bilan-ishlash-oson" tabindex="-1">1-topshiriq. Color Picker&#39;da HSB va HEX kodi bilan ishlash (oson) <a class="header-anchor" href="#_1-topshiriq-color-picker-da-hsb-va-hex-kodi-bilan-ishlash-oson" aria-label="Permalink to &quot;1-topshiriq. Color Picker&#39;da HSB va HEX kodi bilan ishlash (oson)&quot;">​</a></h3><p>O&#39;yin interfeysida oltin tanga chizish uchun quyidagi parametrlarga ega oltin rangni Color Picker orqali qanday topish mumkin:</p><ul><li>Rang burchagi (Hue): 45°;</li><li>To&#39;yinganligi (Saturation): 90%;</li><li>Yorqinligi (Brightness): 95%? Ushbu rangning taxminiy HEX kodini aniqlang.</li></ul><p><strong>Yechim:</strong></p><ol><li>Photoshopda Foreground Color ustiga ikki marta bosilib, Color Picker ochiladi.</li><li>HSB bo&#39;limidagi kataklarga mos ravishda yoziladi: <code>H: 45</code>, <code>S: 90%</code>, <code>B: 95%</code>.</li><li>Natijada yorqin tilla-sariq rang hosil bo&#39;ladi.</li><li>Pastki <code>#</code> maydonida uning olti xonali kodi ko&#39;rinadi (taxminan <code>#F2BF18</code> yoki <code>#F3C017</code>). Ushbu kodni ko&#39;chirib olib, o&#39;yin kodiga qo&#39;yish mumkin.</li></ol><h3 id="_2-topshiriq-radial-gradient-bilan-sehrli-qalqon-nuri-chizish-o-rta" tabindex="-1">2-topshiriq. Radial Gradient bilan sehrli qalqon nuri chizish (o&#39;rta) <a class="header-anchor" href="#_2-topshiriq-radial-gradient-bilan-sehrli-qalqon-nuri-chizish-o-rta" aria-label="Permalink to &quot;2-topshiriq. Radial Gradient bilan sehrli qalqon nuri chizish (o&#39;rta)&quot;">​</a></h3><p>O&#39;yin qahramonining atrofida aylanma ko&#39;k nur taratuvchi shaffof sehrli qalqon (Magic Shield) hosil qilish kerak. Gradient Tool va Gradient Editor yordamida ushbu shaffof nurni qanday yaratish mumkin?</p><p><strong>Yechim:</strong></p><ol><li>Qahramon ustidan yangi bo&#39;sh qatlam ochiladi (Layer: <code>Shield_Aura</code>).</li><li><code>Gradient Tool (G)</code> tanlanadi va turi <strong>Radial Gradient</strong> ga o&#39;tkaziladi.</li><li>Gradient Editor ochiladi: <ul><li>Pastki ranglar: Markazda och moviy (<code>#00FFFF</code>), chekkada to&#39;q ko&#39;k (<code>#002288</code>).</li><li>Yuqori shaffoflik (Opacity): Markaziy nuqta 80%, eng chekka nuqta esa 0% (butunlay shaffof) qilinadi.</li></ul></li><li>Qahramonning ko&#39;krak markazidan boshlab tashqariga qarab sichqoncha bilan radius chizig&#39;i tortiladi.</li><li>Qatlamning Blending rejimi <code>Screen</code> yoki <code>Color Dodge</code> ga o&#39;tkaziladi — natijada chetlari mayin shaffoflashuvchi jozibador radial qalqon paydo bo&#39;ladi.</li></ol><h3 id="_3-topshiriq-3-bosqichli-dinamik-health-bar-paneli-qiyin" tabindex="-1">3-topshiriq. 3 bosqichli dinamik Health Bar paneli (qiyin) <a class="header-anchor" href="#_3-topshiriq-3-bosqichli-dinamik-health-bar-paneli-qiyin" aria-label="Permalink to &quot;3-topshiriq. 3 bosqichli dinamik Health Bar paneli (qiyin)&quot;">​</a></h3><p>O&#39;yinda qahramonning joni to&#39;laligidan to kritik holatgacha pasayishini bitta Gradient bilan ifodalovchi progress bar dizaynini yaratmoqchisiz:</p><ul><li>Jon 100% da — Yashil;</li><li>Jon 50% da — Sariq;</li><li>Jon 10% da — Qizil. Gradient Editor orqali ushbu 3 rangli mayin o&#39;tuvchi chiziqli gradiyentni qanday sozlash kerak?</li></ul><p><strong>Yechim:</strong></p><ol><li><code>Gradient Editor</code> ochiladi va <code>Linear Gradient</code> tanlanadi.</li><li>Pastki rang chizig&#39;ida 3 ta rang to&#39;xtash nuqtasi (Color Stops) joylashtiriladi: <ul><li>1-nuqta (Location: 0%): Qizil rang (<code>#FF1122</code>);</li><li>2-nuqta (Location: 50%): Sariq rang (<code>#FFCC00</code>);</li><li>3-nuqta (Location: 100%): Yashil rang (<code>#22CC44</code>).</li></ul></li><li>Yuqori shaffoflik nuqtalari (Opacity Stops) barcha nuqtalarda 100% saqlanadi.</li><li>UI qatlamida to&#39;rtburchak shakl chizilib, ushbu gradiyent chapdan o&#39;ngga tortiladi.</li><li>O&#39;yin dasturida jon kamaygan sari chiziq o&#39;ng tomondan qisqarib boradi: yashil zonadan sariqqa, undan so&#39;ng qizil kritik zonaga o&#39;tadi.</li></ol><hr>',15))]),i("div",q,[i("h2",b,[o(n,{name:"file-text"}),a[9]||(a[9]=l(" Tezkor nazorat savollari ",-1)),a[10]||(a[10]=i("a",{class:"header-anchor",href:"#tezkor-nazorat-savollari","aria-label":'Permalink to "<Icon name="file-text" /> Tezkor nazorat savollari"'},"​",-1))]),a[11]||(a[11]=r("<ol><li>Dizaynerlar uchun eng qulay bo&#39;lgan HSB modelidagi harflar qanday ma&#39;noni anglatadi? <ul><li><em>Javob:</em> Hue (Tus/burchak 0-360°), Saturation (To&#39;yinganlik 0-100%), Brightness (Yorqinlik 0-100%).</li></ul></li><li>Eyedropper Tool (I) ning o&#39;yin dizayneriga beradigan asosiy foydasi nima? <ul><li><em>Javob:</em> Xolstdagi yoki internetdan olingan tayyor namunadagi rangni bir zumda aniq nusxalab olish imkonini beradi.</li></ul></li><li>Markazdan tashqariga doira shaklida tarqaluvchi gradiyent turi qanday ataladi? <ul><li><em>Javob:</em> Radial Gradient (Aylanma gradiyent).</li></ul></li><li>Photoshopda yig&#39;ilgan maxsus ranglar palitrasini fayl sifatida eksport qilish formati qaysi? <ul><li><em>Javob:</em> <code>.aco</code> (Adobe Color Swatch).</li></ul></li></ol><hr>",2))]),i("div",p,[i("h2",f,[o(n,{name:"file-text"}),a[12]||(a[12]=l(" Keng tarqalgan xatolar va ularning oldini olish ",-1)),a[13]||(a[13]=i("a",{class:"header-anchor",href:"#keng-tarqalgan-xatolar-va-ularning-oldini-olish","aria-label":'Permalink to "<Icon name="file-text" /> Keng tarqalgan xatolar va ularning oldini olish"'},"​",-1))]),a[14]||(a[14]=i("ul",null,[i("li",null,[i("strong",null,`Gradiyentda "Kir kulrang" zona paydo bo'lishi:`),l(" O'quvchilar ko'pincha komplementar ranglar (masalan, qizil va yashil) o'rtasida to'g'ridan-to'g'ri gradiyent tortishadi. Ikki qarama-qarshi rang o'rtasida muqarrar ravishda xira iflos kulrang zona paydo bo'ladi. Buning oldini olish uchun ularning o'rtasiga qo'shimcha sariq yoki olovrang oraliq rang qo'yish kerak.")]),i("li",null,[i("strong",null,"Ko'p rangli tartibsizlik (Swatches ishlatmaslik):"),l(" Bitta o'yin sahnasidagi o'nlab elementlar har xil tasodifiy ranglarga bo'yaladi. Har doim ish boshlashdan oldin Swatches panelida 4-5 ta rangdan iborat bitta rasmiy guruh ochilishi va faqat shu ranglardan foydalanilishi shart.")]),i("li",null,[i("strong",null,"Gradiyent qadamlarining ko'rinib qolishi (Color Banding):"),l(" Agar juda katta 4K xolstda juda yaqin ranglar orasida gradiyent tortilsa, mayin o'tish o'rniga pog'onali chiziqlar (chiziq-chiziq chandiqlar) paydo bo'ladi. Buni yo'qotish uchun gradiyent ustiga 1% "),i("code",null,"Noise"),l(" (shovqin) filtri qo'shiladi yoki 16-bit rang chuqurligi tanlanadi.")])],-1))])])}const C=t(h,[["render",v]]);export{T as __pageData,C as default};
